from z3 import *

def solve():
    E = {}
    for i in range(15):
        for j in range(i+1, 15):
            E[(i, j)] = Bool(f'e_{i}_{j}')

    s = Solver()

    # Fixed edges
    fixed = [(2,12), (3,10), (6,9), (3,13), (3,12), (0,13)]
    for i, j in fixed:
        if i > j:
            i, j = j, i
        s.add(E[(i, j)] == True)

    # Girth >= 4 (no triangles)
    for i in range(15):
        for j in range(i+1, 15):
            for k in range(j+1, 15):
                s.add(Not(And(E[(i, j)], E[(j, k)], E[(i, k)])))

    # Degree constraints
    for i in range(15):
        deg = []
        for j in range(15):
            if i < j:
                deg.append(If(E[(i, j)], 1, 0))
            elif i > j:
                deg.append(If(E[(j, i)], 1, 0))
        s.add(Sum(deg) >= 2)
        s.add(Sum(deg) <= 5)

    if s.check() == sat:
        m = s.model()
        edges = []
        for i in range(15):
            for j in range(i+1, 15):
                if is_true(m[E[(i, j)]]):
                    edges.extend([i, j])
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

def solve():
    # Map (i, j) to 1..105
    var_map = {}
    idx = 1
    for i in range(15):
        for j in range(i+1, 15):
            var_map[(i, j)] = idx
            idx += 1

    solver = Glucose3()

    # Fixed edges
    fixed = [(2,12), (3,10), (6,9), (3,13), (3,12), (0,13)]
    for i, j in fixed:
        if i > j:
            i, j = j, i
        solver.add_clause([var_map[(i, j)]])

    # No triangles
    for i in range(15):
        for j in range(i+1, 15):
            for k in range(j+1, 15):
                solver.add_clause([-var_map[(i, j)], -var_map[(j, k)], -var_map[(i, k)]])

    # Degree constraints
    top_id = 106
    for i in range(15):
        incident = []
        for j in range(15):
            if i < j:
                incident.append(var_map[(i, j)])
            elif i > j:
                incident.append(var_map[(j, i)])

        # Degree >= 2
        cnf_ge = CardEnc.atleast(lits=incident, bound=2, top_id=top_id, encoding=EncType.seqcounter)
        for clause in cnf_ge.clauses:
            solver.add_clause(clause)
        top_id = max([top_id] + [abs(l) for c in cnf_ge.clauses for l in c]) + 1

        # Degree <= 5
        cnf_le = CardEnc.atmost(lits=incident, bound=5, top_id=top_id, encoding=EncType.seqcounter)
        for clause in cnf_le.clauses:
            solver.add_clause(clause)
        top_id = max([top_id] + [abs(l) for c in cnf_le.clauses for l in c]) + 1

    if solver.solve():
        model = solver.get_model()
        edges = []
        for i in range(15):
            for j in range(i+1, 15):
                if model[var_map[(i, j)] - 1] > 0:
                    edges.extend([i, j])
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()
